
-- Batch 4: Central Asia + Europe recipes
INSERT INTO public.recipes (name, slug, country, continent, category, difficulty, prep_time, cook_time, servings, summary, history, ingredients, steps, tags, image_url) VALUES
('Shashlik', 'shashlik-uzbekistan', 'Uzbekistan', 'Asia', 'Main Course', 'Easy', 240, 15, 6, 'Marinated meat skewers grilled over charcoal, a Central Asian BBQ tradition.', 'Shashlik is the quintessential Central Asian grilled meat, descended from ancient nomadic cooking over open fires. The word comes from the Turkic "şiş" meaning skewer.', '["2 lbs lamb or beef, cubed","2 onions, grated","1/4 cup vinegar","1 tsp cumin","Salt and pepper","Fat tail pieces (optional)","Flatbread for serving"]'::jsonb, '["Marinate meat in grated onion, vinegar, cumin overnight","Thread onto metal skewers, alternating with fat pieces","Grill over hot charcoal, turning frequently","Cook 10-15 minutes until charred outside, pink inside","Serve on flatbread with raw onions and sumac"]'::jsonb, ARRAY['Uzbek','Central Asian','Grilled','BBQ'], 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=800'),

('Lagman', 'lagman-uzbekistan', 'Uzbekistan', 'Asia', 'Main Course', 'Medium', 30, 40, 4, 'Hand-pulled noodles in a savory lamb and vegetable broth, a Silk Road staple.', 'Lagman traces its origins to Chinese lamian noodles that traveled west along the Silk Road. In Central Asia, it evolved with local ingredients and became a defining dish of Uzbek and Uyghur cuisine.', '["For noodles: 3 cups flour, 1 cup water, 1 tsp salt, oil","1 lb lamb, cubed","2 onions, diced","2 bell peppers, diced","3 tomatoes, chopped","4 cloves garlic","1 tbsp cumin","Fresh herbs","4 cups broth"]'::jsonb, '["Make noodle dough, rest 1 hour, pull into long strands","Brown lamb in oil, add onions and peppers","Add tomatoes, garlic, cumin, cook 5 minutes","Pour in broth, simmer 25 minutes","Boil hand-pulled noodles until tender","Place noodles in bowls, ladle stew on top","Garnish with fresh herbs"]'::jsonb, ARRAY['Uzbek','Silk Road','Noodles','Hand-Pulled'], 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?w=800'),

('Beshbarmak', 'beshbarmak-kazakhstan', 'Kazakhstan', 'Asia', 'Main Course', 'Medium', 30, 120, 8, 'Boiled meat served over flat noodles with onion sauce - Kazakhstan''s national dish meaning "five fingers".', 'Beshbarmak literally means "five fingers" because it was traditionally eaten by hand. It''s the most important dish in Kazakh culture, served at all celebrations and to honor guests.', '["3 lbs horse meat or beef (bone-in)","4 cups flour for noodles","3 large onions, sliced into rings","Black pepper","Bay leaves","Salt","Fresh dill and parsley","Broth for serving"]'::jsonb, '["Boil meat with bay leaves and salt for 2-3 hours until very tender","Make noodle dough, roll thin, cut into large squares","Cook noodles in the meat broth","Sauté onion rings in broth and fat until soft","Slice meat, arrange over noodles on a large platter","Top with sautéed onions","Serve broth on the side in cups","Eat with hands traditionally"]'::jsonb, ARRAY['Kazakh','Central Asian','National Dish','Noodles','Ceremonial'], 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800'),

('Dolma', 'dolma-turkey', 'Turkey', 'Asia', 'Appetizer', 'Medium', 45, 60, 6, 'Grape leaves stuffed with spiced rice, pine nuts, and herbs - an Ottoman classic.', 'Dolma spread throughout the Ottoman Empire and has deep roots in Turkish, Armenian, and Greek cuisines. The name comes from the Turkish "dolmak" meaning "to be stuffed."', '["40 grape leaves (jarred)","1.5 cups short-grain rice","1 onion, finely diced","1/4 cup pine nuts","1/4 cup currants","2 tbsp olive oil","1 tsp allspice","Fresh mint and dill","Lemon juice","Salt and pepper"]'::jsonb, '["Rinse grape leaves and blanch briefly","Sauté onion in olive oil, add rice and toast","Add pine nuts, currants, spices, herbs","Place a spoonful of filling on each leaf, roll tightly","Arrange rolls seam-side down in a pot","Add water and lemon juice to cover","Place a plate on top to weight down","Simmer for 50-60 minutes","Serve cold with yogurt and lemon"]'::jsonb, ARRAY['Turkish','Ottoman','Stuffed','Vegetarian','Mediterranean'], 'https://images.unsplash.com/photo-1529059997568-3d847b1154f0?w=800'),

('Khachapuri', 'khachapuri-georgia', 'Georgia', 'Asia', 'Bread', 'Medium', 120, 20, 4, 'Georgian cheese-filled bread shaped like a boat, topped with a runny egg and butter.', 'Khachapuri is Georgia''s most famous dish, with each region having its own variation. The Adjarian version with its boat shape, egg, and butter is the most iconic internationally.', '["3 cups flour","1 cup warm milk","1 tbsp yeast","1 tbsp sugar","500g mixed Georgian cheese (sulguni and imeruli)","4 eggs (1 for dough, 3 for topping)","3 tbsp butter","Salt"]'::jsonb, '["Mix yeast with warm milk and sugar, let activate","Make dough with flour, egg, yeast mixture; knead and rise 1 hour","Mix cheeses together","Divide dough into portions, roll into ovals","Shape into boats with raised edges, fill with cheese","Bake at 475°F for 12-15 minutes until golden","Remove, make a well, crack an egg into each","Return to oven for 2-3 minutes until egg is just set","Add butter, swirl into cheese and egg before eating"]'::jsonb, ARRAY['Georgian','Cheese','Bread','Egg','Adjarian'], 'https://images.unsplash.com/photo-1586348943529-beaae6c28db9?w=800'),

('Kebab', 'kebab-turkey', 'Turkey', 'Asia', 'Main Course', 'Easy', 20, 15, 4, 'Seasoned ground meat grilled on skewers, a Turkish classic found worldwide.', 'Kebabs have been part of Middle Eastern and Central Asian cuisine for thousands of years. Turkish kebab culture is particularly rich, with cities like Adana and Iskender giving their names to specific styles.', '["1.5 lbs ground lamb or beef","1 onion, grated","2 cloves garlic, minced","1 tsp cumin","1 tsp paprika","1/2 tsp chili flakes","Fresh parsley","Salt and pepper","Flatbread, onions, sumac for serving"]'::jsonb, '["Mix meat with grated onion, garlic, and spices","Knead well for 5 minutes to develop texture","Shape onto flat metal skewers","Grill over charcoal for 5-7 minutes per side","Rest briefly","Serve on warm flatbread with grilled vegetables","Accompany with yogurt, sumac onions, and pickled peppers"]'::jsonb, ARRAY['Turkish','Grilled','Meat','Street Food'], 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=800'),

('Qabuli', 'qabuli-afghanistan', 'Afghanistan', 'Asia', 'Main Course', 'Medium', 30, 90, 6, 'Afghan pilaf rice with tender lamb, topped with caramelized carrots and raisins.', 'Qabuli Palaw is Afghanistan''s national dish. The combination of savory rice, sweet carrots, and raisins reflects the Central Asian tradition of mixing sweet and savory flavors in rice dishes.', '["2 cups basmati rice","1 lb lamb shoulder, cubed","2 large carrots, julienned","1/2 cup raisins","1 large onion, sliced","2 tbsp oil","1 tsp cardamom","1 tsp cumin","Salt to taste"]'::jsonb, '["Brown lamb in oil, add onion and cook until soft","Add water, cardamom, cumin; simmer 1 hour until tender","Separately caramelize carrots with a little sugar","Soak raisins in warm water","Cook rice until 80% done, drain","Layer rice over meat in pot","Top with carrots and raisins","Cover tightly, steam on low for 20 minutes","Invert onto platter so meat is on top"]'::jsonb, ARRAY['Afghan','Pilaf','Rice','Lamb','National Dish'], 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=800'),

('Kheer', 'kheer-india', 'India', 'Asia', 'Dessert', 'Easy', 10, 45, 6, 'A creamy Indian rice pudding slow-cooked with milk, sugar, cardamom, and nuts.', 'Kheer has been made in India for over 2,000 years and is mentioned in ancient texts. It''s considered an auspicious dessert served at temples, weddings, and festivals across the subcontinent.', '["1/2 cup basmati rice","6 cups whole milk","3/4 cup sugar","1/2 tsp cardamom powder","2 tbsp each: almonds, pistachios, cashews","1 tbsp raisins","Saffron strands (optional)","Rose water (optional)"]'::jsonb, '["Wash and soak rice for 30 minutes","Bring milk to a boil in a heavy-bottomed pot, stirring often","Add drained rice, reduce heat to low","Simmer for 35-40 minutes, stirring frequently to prevent sticking","Milk should reduce by half and rice should be very soft","Add sugar, cardamom, and saffron","Cook 5 more minutes","Garnish with nuts and raisins","Serve warm or chilled"]'::jsonb, ARRAY['Indian','Dessert','Rice Pudding','Sweet','Festival'], 'https://images.unsplash.com/photo-1571091718767-18b5b1457add?w=800'),

('Coq au Vin', 'coq-au-vin-france', 'France', 'Europe', 'Main Course', 'Hard', 30, 120, 6, 'Chicken braised in red wine with mushrooms, pearl onions, and bacon - a French bistro classic.', 'Coq au Vin is one of France''s most celebrated dishes, popularized by Julia Child in America. Originally it used an old rooster (coq) to make tough meat tender through long braising in wine.', '["1 whole chicken, cut into pieces","1 bottle red Burgundy wine","200g bacon lardons","200g pearl onions","200g mushrooms","3 cloves garlic","2 tbsp tomato paste","2 tbsp flour","Fresh thyme and bay leaf","Butter and oil"]'::jsonb, '["Marinate chicken in wine overnight","Brown bacon, reserve. Brown chicken in bacon fat","Remove chicken, sauté onions and mushrooms","Add garlic and tomato paste, cook 2 minutes","Sprinkle flour, stir to coat","Return chicken, pour in wine marinade","Add herbs, bring to simmer","Braise covered for 1.5-2 hours","Add bacon back, adjust seasoning","Serve with crusty bread or mashed potatoes"]'::jsonb, ARRAY['French','Braised','Wine','Classic','Bistro'], 'https://images.unsplash.com/photo-1600891964092-4316c288032e?w=800'),

('Sauerbraten', 'sauerbraten-germany', 'Germany', 'Europe', 'Main Course', 'Hard', 4320, 180, 8, 'German pot roast marinated for days in vinegar and spices, served with potato dumplings.', 'Sauerbraten is one of Germany''s national dishes. The meat is marinated for 3-7 days in a vinegar-wine mixture, resulting in incredibly tender, tangy-sweet beef. Some regions add gingersnap cookies to thicken the gravy.', '["4 lbs beef rump roast","2 cups red wine vinegar","2 cups red wine","2 onions, sliced","2 carrots, sliced","10 juniper berries","6 cloves","3 bay leaves","10 peppercorns","3 tbsp sugar","Gingersnap cookies for sauce","Oil and butter"]'::jsonb, '["Combine vinegar, wine, onions, carrots, and spices for marinade","Submerge beef, refrigerate for 3-5 days, turning daily","Remove beef, pat dry, reserve marinade","Brown beef on all sides in hot oil","Add strained marinade vegetables, cook briefly","Pour in strained marinade liquid","Cover and braise for 2.5-3 hours until fork-tender","Remove meat, strain sauce","Crush gingersnaps into sauce to thicken","Slice meat, serve with sauce and potato dumplings"]'::jsonb, ARRAY['German','Pot Roast','Marinated','Traditional'], 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800');
